import os, base64, shutil
HERE = os.path.dirname(os.path.abspath(__file__))

# Write well_knockout.py
ko_b64 = ''
with open(os.path.join(HERE,"src","well_knockout.py"),"wb") as f:
    f.write(base64.b64decode(ko_b64))
print("  wrote src/well_knockout.py")

# Append plot_knockout_comparison to well_visualizer.py
plot_b64 = ''
vis_path = os.path.join(HERE,"src","well_visualizer.py")
with open(vis_path,"r",encoding="utf-8") as f: vis_src = f.read()
if "plot_knockout_comparison" not in vis_src:
    with open(vis_path,"ab") as f: f.write(base64.b64decode(plot_b64))
    print("  appended plot_knockout_comparison to well_visualizer.py")
else: print("  well_visualizer.py already has knockout plot")

# Patch main.py
mp = os.path.join(HERE,"main.py")
with open(mp,"r",encoding="utf-8") as f: src = f.read()

# Fix CSV encoding
src = src.replace("open(csv_path, 'w', newline='') as f:",
    "open(csv_path, 'w', newline='', encoding='utf-8-sig') as f:")

# Add knockout section
KO_FN = """
def run_knockout_analysis(instance, base_exact_pareto, optimal_schedule, num_steps=12, time_limit=15.0):
    from src.well_knockout import build_knockout_instance, select_knockout_wells, summarise_knockout
    print("\\n  [Knockout] selecting wells...")
    candidates = select_knockout_wells(instance, optimal_schedule)
    ko_summaries = []
    for c in candidates:
        print("\\n  Knocking out: {} ({})".format(c['name'], c['reason']))
        try: ko_inst = build_knockout_instance(instance, c['name'])
        except ValueError as e: print("  SKIP:", e); continue
        ko_exact, _, _, _ = run_exact_pareto_sweep(ko_inst, num_steps=num_steps, time_limit=time_limit)
        ko_ga, _, _ = run_ga_pareto_sweep(ko_inst, generations=150)
        summary = summarise_knockout(c['name'], c['reason'], base_exact_pareto, ko_exact, [], ko_ga, instance['oil_price'])
        ko_summaries.append(summary)
    return ko_summaries
"""
if "run_knockout_analysis" not in src:
    src = src.replace("\ndef interactive_mode", KO_FN + "\ndef interactive_mode")

KO_CALL = """
    best_sched_ko = next((p['schedule'] for p in exact_all
        if p['makespan'] == min(exact_pareto, key=lambda x: x['makespan'])['makespan']), None)
    if best_sched_ko:
        from src.well_visualizer import plot_knockout_comparison
        ko_summaries = run_knockout_analysis(instance, exact_pareto, best_sched_ko)
        if ko_summaries:
            plot_knockout_comparison(exact_pareto, ko_summaries,
                output_path=os.path.join(IMAGES_DIR, 'pareto_knockout.png'),
                oil_price=instance['oil_price'], campaign_label=CAMPAIGN_LABEL)
"""
if "plot_knockout_comparison" not in src:
    src = src.replace('    print("\\n[DONE] All outputs in output/ and images/")',
        KO_CALL + '    print("\\n[DONE] All outputs in output/ and images/")')

with open(mp,"w",encoding="utf-8") as f: f.write(src)
print("  patched main.py")

# Clear pycache
for d in ["src/__pycache__","__pycache__"]:
    full=os.path.join(HERE,d)
    if os.path.exists(full): shutil.rmtree(full)
print("\nDone! Run: python main.py")